class Solution {
    public String shortestPalindrome(String s) {
        String rev = new StringBuilder(s).reverse().toString();
        String combined = s + "#" + rev;
        int[] fail = new int[combined.length()];
        for (int i = 1; i < combined.length(); i++) {
            int j = fail[i - 1];
            while (j > 0 && combined.charAt(i) != combined.charAt(j)) j = fail[j - 1];
            if (combined.charAt(i) == combined.charAt(j)) j++;
            fail[i] = j;
        }
        int palLen = fail[combined.length() - 1];
        return rev.substring(0, s.length() - palLen) + s;
    }
}
